            gate = random.choice(gates)
            if gate == 'NOT':
                circuit.append(('NOT', random.randint(0, len(circuit) - 1)))
            elif gate == 'XOR':
                inputs = random.sample(range(len(circuit)), 2)
                circuit.append(('XOR', inputs[0], inputs[1]))
        return circuit

