        n = len(circuit)
        A = [[0] * (2**n) for _ in range(2**n)]
        for i in range(2**n):
            for j in range(2**n):
                result = 0
                for gate in circuit:
                    if gate[0] == 'NOT':
                        input_index = gate[1]
                        result ^= A[i][input_index]
                    elif gate[0] == 'XOR':
                        input_indices = gate[1:]
                        result ^= (A[i][input_indices[0]] ^ A[i][input_indices[1]])
                A[j][i] = result
        return A

