        else:
            gate = (gate_type, random.sample(range(n), 2))
        circuit.append(gate)
    return circuit

def construct_non_associative_algebra(circuit):
    n = len(circuit)
    algebra = [[0] * n for _ in range(n)]
    for i in range(n):
        algebra[i][i] = 1
    for gate in circuit:
        if gate[0] == 'NOT':
            qubit = gate[1]
            for j in range(n):
                algebra[qubit][j], algebra[j][qubit] = algebra[j][qubit], algebra[qubit][j]
        else:
            qubits = gate[1]
            for j in range(n):
