                    algebra[qubits[0]][j], algebra[j][qubits[0]] = algebra[j][qubits[0]], algebra[qubits[0]][j]
                    algebra[qubits[1]][j], algebra[j][qubits[1]] = algebra[j][qubits[1]], algebra[qubits[1]][j]
    return algebra

def calculate_symplectic_form(algebra):
